(()=>{const root=document.querySelector('#wcd');if(!root)return;const header=root.querySelector('header');const updateHeader=()=>header.classList.toggle('is-scrolled',window.scrollY>24);updateHeader();window.addEventListener('scroll',updateHeader,{passive:true});const menu=root.querySelector('.menu'),nav=root.querySelector('#navigation');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open)});nav.addEventListener('click',e=>{if(e.target.closest('a')){menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}});root.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){menu.setAttribute('aria-expanded','false');nav.classList.remove('open');menu.focus()}});const dialog=root.querySelector('dialog');root.querySelectorAll('[data-design]').forEach(card=>card.addEventListener('click',e=>{e.preventDefault();const source=card.querySelector('img');dialog.querySelector('img').src=source.src;dialog.querySelector('img').alt=source.alt;dialog.querySelector('h2').textContent=card.dataset.design;dialog.querySelector('div > p:not(.eyebrow)').textContent=card.dataset.description;dialog.showModal()}));dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.querySelector('.dialog-link').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}})})();

// Slow, user-controllable rotation. Reduced motion starts paused.
(()=>{const root=document.querySelector('#wcd');if(!root)return;const slides=[...root.querySelectorAll('.hero-slide')],buttons=[...root.querySelectorAll('[data-slide]')],pause=root.querySelector('.hero-pause'),frame=root.querySelector('.hero-art');if(!pause||slides.length<2)return;const motion=matchMedia('(prefers-reduced-motion: reduce)');let current=0,paused=motion.matches,timer=null,hovered=false;function show(index){current=index;slides.forEach((slide,i)=>{slide.classList.toggle('is-active',i===index);slide.setAttribute('aria-hidden',String(i!==index))});buttons.forEach((button,i)=>button.setAttribute('aria-pressed',String(i===index)))}function sync(){clearInterval(timer);timer=null;pause.textContent=paused?'Play slideshow':'Pause slideshow';pause.setAttribute('aria-pressed',String(paused));if(!paused&&!document.hidden&&!hovered)timer=setInterval(()=>show((current+1)%slides.length),9000)}buttons.forEach((button,i)=>button.addEventListener('click',()=>{paused=true;show(i);sync()}));pause.addEventListener('click',()=>{paused=!paused;sync()});frame.addEventListener('mouseenter',()=>{hovered=true;sync()});frame.addEventListener('mouseleave',()=>{hovered=false;sync()});frame.addEventListener('focusin',()=>{clearInterval(timer);timer=null});frame.addEventListener('focusout',event=>{if(!frame.contains(event.relatedTarget))sync()});document.addEventListener('visibilitychange',sync);motion.addEventListener('change',()=>{paused=motion.matches;sync()});show(0);sync()})();

(()=>{const root=document.querySelector('.sizing-guide');if(!root)return;let type='corbels',size=1;const names=['Small','Medium','Large'],scales=[.72,1,1.24];function render(){root.querySelectorAll('[data-guide-type]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.guideType===type)));root.querySelectorAll('[data-guide-size]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.guideSize)===size)));root.querySelector('.scene-corbels').toggleAttribute('hidden',type!=='corbels');root.querySelector('.scene-capitals').toggleAttribute('hidden',type!=='capitals');const s=scales[size];root.querySelector('.room-corbel-left').setAttribute('transform',`translate(159 202) scale(${s})`);root.querySelector('.room-corbel-right').setAttribute('transform',`translate(${543-60*s} 202) scale(${s})`);root.querySelector('.room-capital-left').setAttribute('transform',`translate(${187-50*s} 140) scale(${s})`);root.querySelector('.room-capital-right').setAttribute('transform',`translate(${513-50*s} 140) scale(${s})`);const label=type==='corbels'?'Corbels':'Capitals';root.querySelector('.scene-label').textContent=`${label} · ${names[size]} preview`;root.querySelector('#room-scene-title').textContent=`${label} in a room — ${names[size].toLowerCase()} illustrative size`;}root.querySelectorAll('[data-guide-type]').forEach(b=>b.addEventListener('click',()=>{type=b.dataset.guideType;render()}));root.querySelectorAll('[data-guide-size]').forEach(b=>b.addEventListener('click',()=>{size=Number(b.dataset.guideSize);render()}));render()})();
